// Differential tests for the npps unary / bitwise / shift / reduction families.
// GENERATED by mpp_scripts/gen_unary_diff_tests.py -- DO NOT EDIT.
// A _Ctx case and its plain entry point share one case id so the 5090 recorded
// golden is validated against both MPP entry points.  Integers compare exactly;
// floats use rtol=atol=1e-5.

#include "npp_diff_harness.h"
#include "npp_test_base.h"

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

using namespace npp_diff;
using namespace npp_functional_test;

namespace {

NppStreamContext current_context() {
  NppStreamContext ctx{};
  NppStatus st = nppGetStreamContext(&ctx);
  EXPECT_EQ((int)st, (int)NPP_NO_ERROR) << "nppGetStreamContext failed";
  return ctx;
}

void out2(Case &c, const void *dst, size_t count, ValueKind kind, double rtol = 1e-5, double atol = 1e-5) {
  if (count > 0 && dst != nullptr) c.device_output(static_cast<const Npp8u *>(dst), count, kind, rtol, atol);
}

template <typename T> std::vector<T> make_vec(size_t n, uint64_t s) {
  std::vector<T> v(n); Rng r(s);
  for (auto &x : v) {
    if constexpr (std::is_same_v<T, float> || std::is_same_v<T, double>) x = static_cast<T>(r.unit_double() * 4.0 - 2.0);
    else x = static_cast<T>(r.integer<uint64_t>(0, ~0ULL));
  }
  return v;
}
template <typename T> std::vector<T> make_pos(size_t n, uint64_t s) {
  std::vector<T> v(n); Rng r(s);
  for (auto &x : v) {
    if constexpr (std::is_same_v<T, float> || std::is_same_v<T, double>) x = static_cast<T>(r.unit_double() * 3.0 + 1.0);
    else x = (T)((r.integer<uint64_t>(1, 3000)) % 200) + (T)1;
  }
  return v;
}
std::vector<Npp16sc> make_16sc(size_t n, uint64_t s) { std::vector<Npp16sc> v(n); Rng r(s); for (auto &a : v) { a.re = r.integer<Npp16s>(0, 100); a.im = r.integer<Npp16s>(0, 100); } return v; }
std::vector<Npp32sc> make_32sc(size_t n, uint64_t s) { std::vector<Npp32sc> v(n); Rng r(s); for (auto &a : v) { a.re = r.integer<Npp32s>(-50000, 50000); a.im = r.integer<Npp32s>(-50000, 50000); } return v; }
std::vector<Npp32fc> make_32fc(size_t n, uint64_t s) { std::vector<Npp32fc> v(n); Rng r(s); for (auto &a : v) { a.re = r.unit_float() * 2.f; a.im = r.unit_float() * 2.f; } return v; }
std::vector<Npp64fc> make_64fc(size_t n, uint64_t s) { std::vector<Npp64fc> v(n); Rng r(s); for (auto &a : v) { a.re = r.unit_double(); a.im = r.unit_double(); } return v; }

void finish_case(const char *id, const char *fn, NppStatus st, const void *dst, size_t count,
                 ValueKind kind, double rtol = 1e-5, double atol = 1e-5) {
  Case c(id, fn);
  c.status(st);
  out2(c, dst, count, kind, rtol, atol);
  c.finish();
}

} // namespace

class NppsUnaryArithmetic : public ::testing::Test {
protected:
  void TearDown() override { (void)cudaDeviceSynchronize(); }
};

